-- Generated by scripts/chapters.ts from i18n/frFR/content/: edit those, not this file.
-- chapters[faction][piece] = { title, { paragraph, after = quest, before = quest }, ... }
local _, ns = ...
ns.chapters = {
  [529] = {
    start = { title = "Dans la lumière", { "Entrez, entrez ! Non, restez là, dans la lumière, que je vous voie bien." }, { "Vous avez l'air de quelqu'un qui sait manier une arme et à qui personne n'a encore dit pourquoi. C'est là que j'interviens. L'Aube n'a qu'un ennemi, les morts, et ne se soucie pas le moins du monde du camp que vous avez choisi parmi les vivants. Prenez notre brevet. Ce que le Fléau porte sur lui m'intéresse au plus haut point, et ensuite nous saurons ce que vous êtes." }, { "Encore une chose. Tout ce qui, en ce monde, est poussé trop loin devient son propre ennemi. Le courage. La foi. La Lumière elle-même. Souvenez-vous-en. Je vous poserai la question plus tard." } },
    friendly = { title = "Insignes", { "Vous avez assez arpenté les Maleterres pour que nous parlions en collègues." }, { "Savez-vous ce qu'ils portent sur eux, les morts ? Des insignes. Le Fléau est une armée, et une armée a des grades, même quand ses soldats sont morts. Les pierres communes marquent la piétaille. Les plus rares, l'élite. Les plus rares de toutes appartiennent à ses maîtres, les créatures qui donnent les ordres, et elles valent bien davantage que les autres. Je tiens le compte. Certains soirs, c'est la seule preuve que j'aie que nous sommes en train de gagner." }, { "Chaque lot qu'on m'apporte vaut une marque de valeur. Quelque part dans les Maleterres, une chose qui obéissait aux ordres a cessé d'obéir. J'en éprouve une très grande satisfaction. Je soupçonne que cela dit quelque chose de moi, et je n'ai aucune intention de découvrir quoi." } },
    honored = { title = "Une échine de fer", { "J'avais promis de vous interroger sur les excès. Voici ma question. Comment appelez-vous un homme qui combat le Fléau, prie la Lumière, et tue les innocents parce qu'il ne prend pas la peine de les distinguer des coupables ? La Croisade écarlate l'appelle un croisé. Moi, je l'appelle un blasphémateur !" }, { "Ils tiennent une partie de Stratholme. Là, un homme du nom de Galford garde leurs archives, des années de ce qu'il leur plaît d'appeler du renseignement." }, { "Je veux qu'elles brûlent. Je le veux mort. Dites-moi que c'est déraisonnable. Allez-y.", before = 5251 }, { "Vous les avez brûlées pour moi, et cette nuit-là j'ai mieux dormi que depuis des années. Dites-moi que c'était déraisonnable. Allez-y.", after = 5251 }, { "Voyez-vous, nous autres de l'Aube sommes tolérants. La tolérance n'est pas de la mollesse. Il lui faut une échine de fer, sans quoi le premier fanatique venu la pliera en deux. J'ai une échine de fer." } },
    revered = { title = "Ceux qui reviennent", { "Vous aurez remarqué que je suis toujours là quand vous revenez. J'envoie. C'est ce que je fais. J'envoie des gens comme vous à Stratholme et dans les champs des morts, et j'attends à l'Espoir de Lumière en comptant ce qui revient, les pierres et les gens. Les pierres reviennent toujours." }, { "Alors je tiens deux comptes. Les pierres vont dans le registre, où les intendants peuvent les voir. L'autre compte, je ne le tiens nulle part, et je pourrais vous en réciter chaque ligne." }, { "Vous aurez aussi remarqué que je ne dis jamais de la piétaille du Fléau qu'elle est faible. Je l'ai appris de ceux qui ne sont pas revenus." }, { "Naxxramas est là-haut, la citadelle de Kel'Thuzad, et l'Aube y enverra du monde. Certains seront ceux que j'aurai d'abord envoyés ailleurs." }, { "Et vous m'avez rapporté de Stratholme la tête d'un démon, et je n'ai pas encore décidé de ce qu'elle signifie. Ces gens en rouge croyaient servir la Lumière. Ils servaient un seigneur de l'effroi. Je les ai appelés blasphémateurs. J'aimerais savoir comment les appeler maintenant.", after = 5262 } },
    aside = { title = "L'aparté", { "Vous revenez toujours. J'ai cessé d'en être surpris, ce qui, je vous préviens, est le premier pas pour finir par en dépendre." } },
    exalted = { title = "$gChampion:Championne;", { "$gChampion:Championne;." }, { "Agenouillez-vous. Non, ne vous agenouillez pas. Je ne suis pas un roi, et vous vous relèveriez avec cette tête-là." }, { "Je n'ai donné ce nom à personne depuis bien des années. J'aimerais que vous compreniez que je ne l'emploie pas à la légère, parce que je n'emploie rien à la légère, comme vous l'aurez peut-être remarqué." }, { "Je vous ai dit un jour que tout ce qui est poussé trop loin devient son propre ennemi. J'y ai beaucoup réfléchi depuis, et c'est votre faute. Je suis un homme qui brûlerait une bibliothèque pour la Lumière et appellerait la fumée un sermon. Si quelqu'un, dans cette chapelle, risque de devenir ce qu'il hait, $gmon ami:mon amie;, ce n'est pas vous." }, { "C'est pour cela que j'ai besoin de vous. $gUn champion:Une championne; n'est pas quelqu'un qui me donne raison. C'est quelqu'un dont j'attends qu'il me dise quand je suis allé trop loin, et que je croirai. Je n'en ai pas eu depuis très longtemps." }, { "La guerre n'est pas finie. Un jour, l'Aube marchera contre le maître de tout ceci, où qu'il siège, et ce jour-là, j'aimerais beaucoup vous avoir près de moi. Pas devant moi. Près." } },
  },
  [576] = {
    start = { title = "La porte", { "Je vous ai $gvu:vue; monter la route. Vous voulez le tunnel. Les étrangers veulent toujours le tunnel, parce qu'il est plus court que les montagnes. Il n'est pas à vous." }, { "Nous sommes les Grumegueules, la dernière tribu que la corruption n'a pas prise. Les autres, vous les avez croisés. Tout le monde les a croisés, et tout le monde tire le premier, maintenant, sans prendre le temps de regarder. Alors nous aussi." }, { "Grifleur vous dira comment nous faire changer d'avis. Grifleur dit tout à tout le monde. Faites ce qu'il demande, et puis refaites-le." }, { "Je serai là, à la porte. Je n'ai qu'un oeil. Pour vous, il suffit." } },
    friendly = { title = "Le compte", { "À partir de maintenant, on compte." }, { "Ceux qui rapportent des plumes, prises sur les coiffures des Mort-bois, les donnent à Nafien, devant l'entrée, ou à Grifleur. Ils me donnent le compte, que je le demande ou non. Je n'y prends aucun plaisir. Les Mort-bois étaient des nôtres avant que la gangrène ne gagne Gangrebois, puis eux. Une plume ne dit pas de quel Mort-bois elle vient." }, { "Les perles, c'est pire. Les Tombe-hiver les portaient contre les mauvais esprits. Vous voyez le résultat. Ils portaient leurs protections, le mal est entré quand même, et maintenant leurs perles arrivent chez Salfa dans les sacs des étrangers." }, { "Salfa vous trouve utile, et Salfa se trompe rarement. Moi, je vous surveille encore." } },
    honored = { title = "Ce que peu ont demandé", { "Vous traversez le repaire si souvent que les gardes ne portent plus la main à leur arme quand vous passez. Alors voici quelque chose, et vous en ferez ce que les vôtres font de ce qu'on leur confie." }, { "Les elfes de la nuit ont accepté notre aide, une fois, contre les démons, et beaucoup l'ont acceptée en se pinçant le nez. Certains se le pincent toujours. Demandez aux Sentinelles, un jour où elles se sentent honnêtes." }, { "Les Tombe-hiver étaient nos amis, et il n'y a pas si longtemps. Puis leur grand chef s'est mis à vouloir des choses que personne ne comprenait, et sa tribu s'est retournée contre tout ce qui l'entourait, nous compris. Depuis, nous restons entre nous. Nous avons au moins appris cela." }, { "Les vôtres écrivent leur histoire. Pas nous. Et ce qui nous est le plus cher, vous l'avez traversé cent fois sans le voir. Pas encore." } },
    revered = { title = "Dit une fois", { "Je ne le dirai qu'une fois, et vous ne le répéterez pas à Grifleur." }, { "Nous ne pouvons pas tenir ce lieu seuls. Salfa le dit aux étrangers, parce que Salfa est d'une honnêteté sans bornes. Moi, je vous le dis parce que... Non. Je te le dis parce que tu n'es plus $gun étranger:une étrangère;, ce que je ne pensais pas dire cette année. Si les Tombe-hiver et les Mort-bois venaient sur nous des deux côtés à la fois, il nous faudrait tous nos amis, et nous n'en avons pas beaucoup." }, { "Les rois des tiens ont déjà envoyé des messages à ce repaire. Le roi des nains, sous sa montagne. Le chef de guerre des orcs, en Durotar. Ils voulaient parler. Il n'y a pas eu de paix. Je pourrais t'en donner les raisons, mais elles ne te plairaient pas, et la plupart parleraient des tiens." }, { "Tu es $gRévéré:Révérée; parmi nous. Ici, le mot veut dire quelque chose de plus simple que chez les tiens. Il veut dire que si tu tombais devant la porte, quelqu'un sortirait te chercher. Ce serait moi. Je ronchonnerais tout le long." } },
    aside = { title = "L'aparté", { "Toujours là. Je compte toujours. Salfa dit que tu es à mi-chemin de quelque chose. Salfa aime dire ce genre de choses. Quand tu seras $garrivé:arrivée;, c'est de moi que tu l'entendras." } },
    exalted = { title = "Plus lentement", { "À partir de maintenant, traverse le repaire plus lentement. Tu le feras, une fois que tu sauras pourquoi." }, { "Tu crois que ce lieu est une route. Une bonne route, à l'abri de la neige, avec dedans des furbolgs qui ont appris à ne plus te tirer dessus. Ça n'a jamais été une route. Le repaire a été fait pour Ursoc et Ursol, les ours jumeaux que nous honorons, et chaque tunnel que tu as traversé en hâte pour t'épargner une montagne en fait partie. Nous laissons ceux en qui nous avons confiance traverser un lieu sacré. La plupart n'ont jamais su ce que c'était. Toi, maintenant, tu sais." }, { "Tu vas me poser la question de l'oeil. Tous ceux qui arrivent jusqu'ici posent la question de l'oeil. Non." }, { "J'ai été le dernier de ce repaire à te faire confiance, et je tiens à ce qu'on s'en souvienne, parce que j'avais raison d'être lent. La confiance qui vient facilement repart de même. La mienne est venue lentement, et elle ne partira pas." }, { "Il y a encore une chose, et nous ne la donnons pas à beaucoup. À une mauvaise heure, loin d'ici, un de nos ancêtres viendra se tenir à tes côtés, et te soignera tout en se battant. Pas pour les petites misères. Ils sont vieux, ils sont à nous, et ils viennent par égard pour moi.", after = 8481 } },
  },
  [59] = {
    start = { title = "Insectes", { "Un insecte. À ma table. Qui me parle." }, { "Nous ne faisons pas affaire avec les insectes, et je n'ai aucune patience pour eux. Vous n'avez rien que je veuille, vous ne savez rien dont j'aie besoin, et vous me cachez la porte. La Confrérie a tourné le dos à l'empereur il y a bien longtemps. Je bois toujours dans sa cité. Ni l'un ni l'autre ne vous regarde." }, { "La Confrérie tient une maison pour les égarés, à la Halte du Thorium, où l'on est plus aimable. Soyez d'abord $gun égaré:une égarée; là-bas. Si jamais ils apprennent votre nom, revenez, et j'envisagerai de l'apprendre aussi." }, { "D'ici là, dehors. Dehors." } },
    friendly = { title = "Les conditions", { "La Halte du Thorium connaît votre nom. Bien. Tenez-vous où je peux vous voir, et écoutez les conditions." }, { "Nous sommes descendus autrefois dans les salles du seigneur du Feu, pour ses noyaux, son cuir et le sang de la montagne, qui n'est autre que ses larmes. Beaucoup des nôtres sont descendus et ne sont jamais remontés. Maintenant, c'est vous qui descendez. Vous coûtez moins cher. Rien de personnel. Chez TB Ltd., rien ne l'est jamais." }, { "La faveur ouvre les livres de la Confrérie, les plans et les patrons que personne d'autre au monde ne vous vendra. C'est la seule monnaie que j'accepte qui ne se ternisse pas. L'or, je peux l'avoir de n'importe qui." }, { "L'offrande est pesée. L'offrande est jugée suffisante. Que cela ne vous monte pas à la tête." } },
    honored = { title = "Le petit couteau", { "La Confrérie vous reçoit, et prend acte de votre... oh, asseyez-vous, si vous voulez. Personne ne s'assied avec moi. C'est à cela qu'on reconnaît un honneur." }, { "Vous croyez que nous sommes des Sombrefer qui se sont découvert une conscience. C'est à moitié vrai. Nous étions une guilde avant d'être quoi que ce soit d'autre, une guilde d'artisans à Forgefer, du temps où il n'y avait qu'un seul Forgefer et où les clans ne s'étaient pas encore fait la guerre pour lui. Une guilde qui avait peur. Nous étions sûrs que nos rivaux connaissaient des secrets que nous ignorions. Alors nous nous sommes procuré leurs plus beaux ouvrages et nous les avons démontés pour voir. C'est comme cela que nous avons trouvé l'enchantement. Pas par l'étude. Par le vol, la patience, et un tout petit couteau." }, { "Quand la guerre est venue et que les clans ont choisi leur camp, nous avons choisi. Vous savez lequel. Je ne m'en excuserai pas devant un étranger, et je n'ai pas encore décidé ce que vous êtes, alors je ne m'en excuserai pas devant vous non plus." }, { "Notre plus beau secret, nous l'avons d'abord volé." } },
    revered = { title = "Le gâchis", { "La Confrérie entendra votre question. C'est moi qui l'entendrai." }, { "Vous voulez savoir pourquoi nous sommes partis. Pas la version courte." }, { "Quand le seigneur du Feu s'est éveillé, la montagne était à lui, et nous aussi. Les gens de l'empereur sont devenus ses serviteurs, et la Confrérie ses forgerons. Nous avons travaillé à ses forges. Nous avons fait ses armes, la même lame encore et encore, pour une armée qui se moquait de la qualité d'un ouvrage. Comprenez-moi bien. Ce n'était pas la cruauté. Un nain supporte la cruauté. C'était le gâchis. Les meilleures mains sous la montagne, à marteler la même épée pour des créatures incapables de la distinguer d'une pire." }, { "C'est mon apprenti qui a trouvé la sortie. Oilfist. Le surveillant Oilfist, maintenant, à la Halte du Thorium, qui dirige l'endroit comme une garnison. Il a tout préparé sous le nez des contremaîtres, et nous avons fabriqué ce qu'il fallait pour sortir des Profondeurs. La plupart de ceux qui se sont libérés ont couru aussi loin que leurs jambes les portaient. Nous, nous nous sommes arrêtés de l'autre côté de la Gorge. Les matériaux sont ici. L'artisanat ne fuit pas." }, { "Et pourquoi suis-je ici, à une table, dans la cité même de l'empereur ? La bière. Question suivante." } },
    aside = { title = "L'aparté", { "Encore vous. Asseyez-vous. Non, pas là. Là. Vous avez mérité la meilleure chaise, qui est la même chaise, mais moi, je le saurai." } },
    exalted = { title = "Associés", { "Plus de cérémonie. Toi et moi, nous n'en sommes plus à peser des offrandes. Écoute. Je te parle franchement, désormais, et je ne te parlerai plus autrement." }, { "La Confrérie détient le secret du marteau du seigneur du Feu. Sulfuras. La grande masse qu'il porte, là-dessous, dans le Cœur. Nous pouvons apprendre à un forgeron à forger le marteau en sulfuron, et une fois l'Oeil de Sulfuras serti dedans, un héros pourrait emporter la Main de Ragnaros à travers le monde. Pense à ce que cela veut dire. Nous avons passé un âge entier à forger des armes pour lui. Aujourd'hui, nous vendons de quoi fabriquer la sienne à quiconque est assez fort pour le tuer, à un prix honnête. Je n'ai jamais été aussi content d'une affaire de toute ma vie." }, { "J'en perds la tête. Pose un lingot de sulfuron devant moi et je crierai. Je le sais. Je m'en moque." }, { "Voici l'autre chose, puisque tu as passé la porte. Une guilde comme la nôtre ne vit pas que de son art. Quand un rival devient trop bon, de temps à autre, sa forge a un accident. Nous ne sommes jamais dans les parages. Tu te souviendras que nous ne sommes jamais dans les parages." }, { "Tu es $garrivé:arrivée; à ma table en insecte. Tu en repars en $gassocié:associée;. Lis tes contrats, tous. Les miens surtout." } },
  },
  [609] = {
    start = { title = "L'autre ennemi", { "Bienvenue au Fort ! Ici, tout le monde surveille les bestioles. Elles sont grosses, elles sont nombreuses, et elles se tiennent dans leurs ruches et derrière ce mur comme si elles attendaient quelque chose, alors je ne reproche à personne de les surveiller." }, { "Mais retourne-toi. Les cultistes du désert, eux, n'attendent pas. Ils bâtissent, ils invoquent, et ils se passent des mots par gribouillis. Mon grand frère Huum et moi, on leur colle aux basques, parce qu'il faut bien que quelqu'un le fasse et que personne d'autre ne le fera." }, { "Des bestioles, on en a plein. Un vrai combat, j'ai mieux." } },
    friendly = { title = "Les gribouillis", { "Ce que je veux le plus, ce sont les papiers du culte. De petits bouts de papier couverts de gribouillis. C'est comme ça que leurs camps se parlent !" }, { "Je ne sais pas les lire, et je n'en ai pas besoin. Chaque liasse prise sur un cultiste mort, c'est un message qui n'arrive jamais, un ordre que personne ne reçoit, un camp qui attend des nouvelles et n'entend rien. Ça aussi, c'est un combat. Un combat silencieux, mais un combat." }, { "Huum voudrait les lire. Huum écoute les choses, la terre, les esprits, les papiers aussi, j'imagine. Moi, je les mets de côté. Un jour, quelqu'un de malin en voudra, et d'ici là, chaque bout de papier de mon tas, c'est un bout que le culte ne lira jamais." } },
    honored = { title = "Mon grand frère", { "Tiens. Tu as mérité une histoire, et j'en ai une, et elle parle surtout de mon frère." }, { "Mon peuple, je le dis toujours, fait les choses lentement, en écoutant d'abord. Huum est des miens jusqu'au bout. Huum écoute d'abord. Il dit que les esprits d'ici l'appellent, que le sable porte le deuil de quelque chose qu'il faudrait que quelqu'un entende." }, { "Moi, je ne l'entends pas. J'ai essayé, fort, comme j'essaie tout. Je me tiens là où il se tient, et je n'ai que du sable dans les oreilles. Mais je le crois. Parce que c'est mon frère. Parce que je n'ai jamais réussi à lui prouver qu'il avait tort. Et parce que quand il se tait, le soir, il se tait trop longtemps." }, { "Alors je me bats, il écoute, et à nous deux, le Fort a ce qu'il lui faut." } },
    revered = { title = "Ce qu'ils appellent", { "Ce qui m'empêche de dormir tient en une courte liste. Ça m'empêche de dormir, alors ça peut bien t'empêcher de dormir aussi." }, { "Le culte ne se contente pas de prier, là-bas. Ils font sortir des choses des pierres d'invocation : des templiers, puis des ducs, puis des seigneurs, chacun plus gros que le précédent et chacun un plus gros mal de tête pour moi. Et chacun donne des ordres. On sait qu'on peut les écraser. Ce qu'on ne sait pas, c'est à qui ils obéissent. Peut-être que le culte les vénère. Peut-être que ce ne sont que des messagers, et que ce qui envoie les messages ne s'est pas encore montré." }, { "Alors, la liste. Les bestioles dans leurs ruches et derrière le mur. Le culte dans le désert. Ce que le culte invoque. Ce qui rend Huum si silencieux, le soir. Ça fait beaucoup d'ennemis pour un seul bout de sable." }, { "Tout le monde me dit d'attendre et de surveiller. Ça fait longtemps que j'attends et que je surveille. Je n'y ai pas pris goût." } },
    aside = { title = "Mon poste", { "Même poste, même sable. Va donc lutter contre les gros à ma place, et reviens me dire s'ils frappent fort !" } },
    exalted = { title = "Le plus gros coffre", { "Tu sais ce que je te donnerais, si je pouvais te donner n'importe quoi ? Mon poste. Rien qu'une seule journée." }, { "Ce coffre ne valait rien du tout comme merci. Je t'ai $gentendu:entendue; rire en l'ouvrant, et je sais bien que ce n'était pas du coffre que tu riais.", after = 8352 }, { "Je sortirais du Fort avec toi, au-delà des camps et des pierres, dans le désert, et on irait chercher la plus grosse chose que le culte sache appeler, pour voir ensemble à quel point elle frappe fort !" }, { "Mais je ne peux pas. Il faut que quelqu'un tienne ici, et c'est moi. Ça a toujours été moi. Alors à la place, je vais te dire la chose que je n'ai jamais dite à personne. Quand Huum se tait, le soir, je le surveille. Lui, pas ce qu'il écoute. C'est lui que je garde. Le Fort, le mur, les papiers, tout ça, je l'échangerais contre lui sans réfléchir, et c'est une chose terrible à dire quand on monte la garde." }, { "Huum me dirait que la terre a plus besoin d'être gardée que lui. Et Huum aurait raison. Il a presque toujours raison. Moi, je le choisirais quand même." }, { "Tu es $gle seul:la seule; à qui je l'aie jamais dit." } },
  },
  [270] = {
    start = { title = "Pas encore", { "Soyez $gle bienvenu:la bienvenue;. On m'appelle Rin'wosho, et je commerce depuis Zuldazar, bien loin de chez moi et plus loin encore de mes meilleurs clients." }, { "Vous voudrez voir ce que je transporte. Tout le monde veut. Des marchandises des Mers du Sud, des patrons pour vos tailleurs et vos travailleurs du cuir, des fruits dont vous ne soupçonnez pas la saveur. Et je serais ravi de vous les vendre. Mais je ne troque qu'avec les amis de ma tribu, et vous n'en êtes pas encore." }, { "Les Zandalar sont en guerre contre un dieu qui aurait dû demeurer dans l'oubli. Aidez-les, puis revenez, et nous parlerons prix." } },
    friendly = { title = "L'honneur, en monnaie", { "Maintenant, nous pouvons faire affaire, $gmon ami:mon amie;." }, { "Chez les Zandalar, cela se passe ainsi. Ce que vous rapportez de Zul'Gurub pour la tribu, elle vous le rend en honneur, en marques à garder et à dépenser chez moi. J'aime un peuple dont la gratitude tient dans une bourse. Dépensez-les ou gardez-les, à votre guise. J'ai connu des gens qui en gardaient une pendant des années, sans pouvoir dire pourquoi." }, { "Les pièces que portent les trolls de cette cité, c'est autre chose. Chacun de ces peuples a la sienne, chacune chargée de mojo, et Vinchaxa les prend pour l'usage de la tribu. Je ne marchanderais pas sur celles-là. Certaines choses valent plus que ce qu'elles achètent." } },
    honored = { title = "La mangue", { "Vous n'avez jamais mangé de mangue d'essence. Nul de ceux qui en ont goûté ne demande ce que c'est." }, { "Elles poussent partout où les Mers du Sud ont une plage pour les accueillir. Une seule, et vous voilà $greposé:reposée; de corps et d'esprit, comme après une nuit passée sur le sable, chez moi. J'en garde une réserve ici, sur l'île, pour ceux que la tribu en est venue à respecter. Je pourrais les vendre à prix d'or, ici. Je n'en fais rien. Certains fruits ne sont que pour les amis." }, { "Ce n'est pas pour son roi ni pour ses prêtres que Zuldazar me manque. C'est pour ses fruits, pour la mer, et pour ma propre langue parlée par des gens qui n'ont pas peur. Ici, tout le monde a peur. On l'entend à la façon dont l'île parle tout bas, une fois le soleil couché. Ici, même les fruits ont le goût d'un pays lointain." } },
    revered = { title = "Ce que les prêtres ont pris", { "Avec votre rang viennent mes breuvages les plus puissants, ceux que Zanza a bénis. Prenez-en un seul à la fois, $gmon ami:mon amie;. Une bénédiction, cela ne s'empile pas." }, { "Écoutez maintenant pourquoi la tribu accorde ses bénédictions à des étrangers. À Zul'Gurub, les grands prêtres sont les esclaves de l'Écorcheur d'âmes, et à travers eux il boit nos dieux. Pas leur sang. Leur force. Chaque jour où il tient cette cité, les plus vieilles puissances que connaît mon peuple faiblissent un peu, et lui se renforce un peu, et personne ne sait me dire où est le fond." }, { "Je dors mal, sur cette île. Un marchand sait ce qui quitte ses étagères, et je ne sais plus mesurer ce qui quitte les dieux. Certains soirs, je marche sur la plage et je parle à la mer dans ma langue, pour que quelque chose, sur cette île, l'entende encore." }, { "Alors quand je vous tends un breuvage béni, ce n'est pas de la générosité. C'est du stock écoulé avant que l'entrepôt ne brûle." } },
    aside = { title = "Client fidèle", { "Une mangue ? Attention. Un marchand qui sert deux fois la même personne s'y attache, et l'attachement est très mauvais pour les prix." } },
    exalted = { title = "De chez moi", { "Ceux-là, je ne les vends à personne d'autre. Des cachets, venus par la mer depuis les Mers du Sud, pour les épaules de ceux que la tribu compte parmi les siens. Puissance, mojo ou sérénité : j'ai ajusté bien des épaules dans ma vie, et peu portaient quelque chose qui en valût le poids." }, { "Sous chaque marché que nous avons conclu, il y a une chose simple. Les pièces vont à la défense de la tribu contre le dieu de cette cité, et les bijoux hakkari sont brisés sur l'autel de Zanza, chaque miette de mojo retournée contre lui. Longtemps, je me suis dit que je ne faisais que vendre. J'ai cessé de le croire il y a quelque temps déjà. Je crois que c'est à peu près quand j'ai commencé à vous garder les meilleures mangues." }, { "Je rentrerai un jour, quand l'Écorcheur d'âmes ne sera plus que cendres et que nos dieux seront entiers. La mer sera toujours là. C'est la seule chose que je n'ai jamais eu à marchander. Le premier soir, je mangerai une mangue sur le sable en pensant à cette vilaine petite île, et je crois bien qu'elle me manquera. Ce jour-là, je leur parlerai de vous, et de vos marchés." } },
  },
  [910] = {
    start = { title = "Hors de vue", { "Inutile de baisser la voix. Peu de ce que disent les mortels porte loin chez les miens. Le vol de bronze n'a plus accordé sa faveur à l'un des vôtres depuis très longtemps, et vous commencez avec nous là où tout mortel commence, c'est-à-dire nulle part." }, { "Ne le prenez pas mal. Ce n'est pas de la haine. Nous sommes lents à prêter attention à ce qui ne durera pas." }, { "Là-bas, au-delà des murs du Fort, la ruche remue. Le sol tremble tout autour, et le vieil ennemi prépare de nouveau sa guerre. C'est cela qui mérite qu'on s'en soucie. C'est pour cela que je suis ici." } },
    friendly = { title = "Les grains", { "Bien. Vous commencez à compter, un peu. Je l'ai senti comme on sent un seul grain glisser dans un sablier : presque rien, et puis impossible de l'ignorer." }, { "Ce que le vol attend des mortels est simple et très difficile. Chaque serviteur des maîtres des insectes qui tombe est un grain qui passe de leur côté du sablier au nôtre. Je veille sur ce sablier depuis longtemps. Il est bon d'y voir une autre main." }, { "Un mot sur le vol de bronze, que vous n'avez pas demandé : nous ne nous pressons pas. Cela ne veut pas dire que nous nous en moquons. Souvenez-vous-en, le jour où nous vous paraîtrons lents." } },
    honored = { title = "Le souffle", { "Je vais vous offrir une vieille histoire, si vous la voulez bien. Je la raconterai sans ornement." }, { "Un jour, je mourais. Je n'avais plus rien à donner, mes blessures étaient ouvertes, et je n'avais plus peur, et c'est ainsi que j'ai su combien la fin était proche. Puis le maître de mon vol est venu à moi." }, { "Je ne me souviens pas du souffle. Je me souviens qu'ensuite, je ne mourais plus, et qu'on m'a dit de demeurer, aussi longtemps qu'il faudrait demeurer. Ainsi m'a été confiée la veille. Je n'ai jamais trouvé de meilleur nom pour cela que celui qu'on m'a donné : guetter." }, { "C'était un geste plein de bonté, et il me coûte depuis. Les deux sont vrais, et j'ai cessé d'essayer de rendre l'un plus petit que l'autre." } },
    revered = { title = "Le serment", { "Il y a longtemps, j'ai prêté un serment, et l'heure est enfin venue de le tenir. Ce qu'il disait m'appartient. Ce que l'on éprouve à le tenir, je peux vous le donner." }, { "C'est comme une porte qu'on a surveillée si longtemps qu'on a oublié qu'elle pouvait s'ouvrir. La ruche remue, les sables se déplacent, les Qiraji s'apprêtent, et soudain l'attente est finie, et je découvre que je ne voulais pas qu'elle finisse. Un serment tenu, c'est un serment qu'on ne porte plus. J'ai porté celui-ci si longtemps que je ne connais plus mon propre poids sans lui." }, { "Un guetteur ne craint qu'une chose, et ce n'est pas l'ennemi. L'ennemi est honnête. Ce que craint un guetteur, c'est l'idée que celui qu'on attend ne reviendra pas, et qu'on continuera d'attendre quand même, par habitude, longtemps après que cela n'aura plus de sens." }, { "Cette pensée m'accompagne chaque jour depuis plus longtemps que les vôtres n'ont de noms." } },
    aside = { title = "Le sablier", { "À mi-chemin, à votre compte. Au mien, un instant. Aucun de nous ne se trompe. Allez. Le sablier ne s'en offusque pas." } },
    exalted = { title = "La faveur", { "Aucun mortel n'a eu la faveur du vol de bronze depuis mille ans. Je me demandais parfois si l'un d'eux l'aurait un jour, comme on se demande s'il pleuvra dans ce désert : par habitude, sans espoir." }, { "Vous l'avez, désormais. Cela veut dire que je ne vous parlerai plus comme on parle à un inconnu. C'est tout ce que cela veut dire, et je trouve que c'est beaucoup. Pendant très longtemps, tous ceux à qui je parlais étaient des inconnus, même ceux qui se tenaient à mes côtés, parce qu'une part de moi regardait toujours le mur." }, { "Vous êtes $gallé:allée; aux Grottes du temps pour moi, et vous avez trouvé le maître revenu. Ma veille est finie. Je ne sais pas encore ce que fait celui qui guette quand il n'y a plus rien à guetter. Restez un peu, et aidez-moi à le découvrir.", after = 8286 }, { "J'ai longtemps attendu que quelque chose arrive. Je ne m'attendais pas à ce que ce soit vous. Attendre avec quelqu'un à ses côtés, c'est autre chose, et j'avais oublié à quel point. Si vous revenez, même bien tard, je vous reconnaîtrai. Avoir eu tort au sujet des mortels me réjouit. De certains, du moins. $gD'un seul:D'une seule;." } },
  },
  [749] = {
    start = { title = "Un marché", { "Vous n'êtes pas $gné:née; de l'eau, et ce pour quoi nous combattons vous restera fermé. Faire semblant n'y changerait rien." }, { "Un marché n'exige pas de comprendre. Les seigneurs de l'Eau combattent ceux de l'air, de la terre et du feu, et le feu est celui que nous ne pardonnons pas. Vous êtes $gpetit:petite;, votre vie est brève, et vous marchez sur une terre qui brûle. Vous avez vos propres raisons de vouloir éteindre le feu. Vos raisons et les nôtres iront peut-être dans le même sens, pour un temps. J'entends en tirer parti." }, { "Rendez-vous utile, et les profondeurs se souviendront de vous. Elles oublient presque tout." } },
    friendly = { title = "La pureté", { "Vous avez été utile. C'est plus rare que vous ne le croiriez, chez les vôtres." }, { "Comprenez ce pour quoi nous nous battons. Vous voilà à nos côtés. Ce qui nous rend forts, c'est notre pureté. L'eau qui prend en elle tout ce qu'elle touche n'est plus de l'eau, seulement une maladie qui coule. Quand la peste de Lordaeron a gagné les élémentaires que nous y avions envoyés, ce qui m'a offensé, c'est ce qu'ils étaient devenus." }, { "Il est une chose dont je ne sais rien. Nos ennemis de l'air et de la terre gardent des objets de pouvoir dans le sud, loin des mortels, et je ne peux pas vous dire pourquoi. Je sais seulement que, quoi qu'ils gardent, je préférerais qu'ils ne le gardent pas." } },
    honored = { title = "Le débat", { "On a parlé de vous dans nos salles, et longuement. Ce n'est pas notre façon. Vous en étiez le sujet, non le juge, et il est juste que vous sachiez comment cela s'est passé." }, { "Certains d'entre nous vous tenaient pour une piètre chose à dépenser dans notre guerre, une créature dans laquelle nous verserions nos forces avant qu'elle ne se fende. Ils n'avaient pas tort, et ils n'ont pas tort aujourd'hui. Vous êtes $gpetit:petite;. Vous vous brisez. Vous êtes $grevenu:revenue; malgré tout, contre nos ennemis, encore et encore, et chaque retour rendait leur avis un peu plus difficile à tenir." }, { "Aucun de nous ne l'aurait cru possible. Les seigneurs de l'Eau vous respectent à présent. Cela trouble l'ordre des choses d'une façon que je ne sais pas nommer, car une petite chose ne devrait pas peser autant, et vous pesez. Ceux qui doutaient se sont tus, comme un courant s'immobilise avant de tourner." } },
    revered = { title = "La perte jugée acceptable", { "L'eau n'a ni pitié ni malveillance. Je parlerai comme elle." }, { "Il nous en coûte de perdre quelqu'un qui a fait ses preuves, et c'est votre cas. Envoyer l'un des vôtres contre les capitaines mêmes du seigneur du Feu est ce que nous exigeons de plus difficile, et nous ne l'exigeons que lorsque nous jugeons que le gain vaut la perte. Ce jugement est le plus beau compliment que les seigneurs de l'Eau sachent faire. Je ne vous reprocherais pas de ne pas l'entendre ainsi. Nous avons déjà dépensé des agents, et l'eau s'est refermée sur eux. Elle ne se refermerait pas si vite sur vous." }, { "Sous la montagne, le sol est gravé de runes de feu. Chacune est une porte vers son royaume, et chacune le nourrit. Quand une rune s'éteint, une porte se ferme, le feu puise un peu moins chez lui, et il est un peu plus seul au monde. C'est tout ce que nous lui voulons : qu'il soit seul, puis qu'il ne soit plus." } },
    aside = { title = "La marée", { "La marée a un peu tourné en notre faveur, et vous y êtes pour quelque chose. Un peu. C'est une grande marée, vous êtes une petite créature, et pourtant elle a bougé." } },
    exalted = { title = "Légende", { "La gratitude est une habitude de mortels. Chez nous, rien n'est dû pour un travail bien fait. Le courant fait son œuvre, et nul ne l'en loue. La mer ne remercie pas la rivière d'être arrivée." }, { "Vous avez combattu pour nous avec une constance que je ne croyais pas possible chez une créature de votre taille, et je veux vous donner quelque chose. J'ai cherché ce que l'un des vôtres pourrait vouloir, sans le trouver. Je vous donne donc ce que nous voudrions, nous, si nous voulions quelque chose. C'est ce que nous avons de plus proche d'un merci, et l'on me dit que chez les vôtres il est d'usage de le dire tout haut. C'est fait. Prenez donc ceci : une source de notre quintessence qui ne tarira pas. Je ne fixe pas de terme." }, { "Vous m'avez rapporté les mains des capitaines du seigneur du Feu. La nouvelle a coulé jusqu'au fond de nos salles comme un courant. J'ai admis un jour que vous finiriez peut-être en légende chez nous. J'étais prudent. Vous en êtes déjà une.", after = 6824 }, { "Vous êtes $gpetit:petite;, et vous ne durerez pas. Je le pense toujours, l'un comme l'autre. Les profondeurs oublient presque tout. Elles ont décidé de vous garder." } },
  },
  [809] = {
    start = { title = "Qui êtes-vous déjà", { "Ah. $gUn visiteur:Une visiteuse;. Quelle nouveauté. Non, ne me dites pas votre nom. Je n'aurais qu'à l'oublier, c'est un tel effort, et le catalogue ne se tiendra pas à jour tout seul." }, { "Quand on tient l'index d'une maison depuis dix mille ans, l'heure d'un mortel devient bien petite, et vos ennuis, quels qu'ils soient, rapetissent avec elle. Je le dis sans méchanceté. Je dis presque tout sans méchanceté. Cela fait gagner du temps." }, { "Chaque tome de ces salles est frappé du sceau de la maison, et beaucoup ne sont pas à leur place. Rapportez-en un, et je commencerai peut-être à me souvenir de vous." } },
    friendly = { title = "Tours de passe-passe", { "Les librams, donc. C'est cela que je veux de vous." }, { "Il y a quelques années, un elfe de Quel'Thalas est venu à nous, Maître Winthalus, qui fuyait la ruine de sa terre avec quelques vieux trésors. Il les a ensuite égarés dans nos salles avec une négligence que je ne peux qualifier que d'héroïque. Chaque libram renferme un petit sort pour votre équipement. Des amusettes. Malgré tout, apportez-m'en un avec les composants qu'il réclame, et je vous en tirerai l'arcanum, et vous pourrez le porter et vous sentir très légèrement moins $gmortel:mortelle; un après-midi durant." }, { "Ne vous méprenez pas sur mon ton. Les librams m'ennuient, et je veux les récupérer jusqu'au dernier. Rien de ce qui est écrit n'est sans valeur. C'est la seule conviction que j'aie gardée intacte en toutes ces années, et je vous saurais gré de ne pas la mettre à l'épreuve." }, { "Qui êtes-vous déjà ? Cela va me revenir." } },
    honored = { title = "La maison", { "Vous tenez à rester dans mes jambes. Autant que vous connaissiez la maison que vous traversez." }, { "Maître Winthalus a sangloté sur un libram perdu. Sangloté. Pour un sortilège de protection. J'ai moi-même versé des larmes sur un livre perdu. Perdre ce qui était su est le seul chagrin que je respecte. Mais on pleure une histoire, pas une amusette." }, { "Le Prince l'a fait écorcher. J'ai parlé de faveur, à l'époque, et j'ai eu tout le temps de me demander si je le pensais. Cela en dit long sur cette maison, ou sur moi, et je préfère ne pas y regarder de trop près." }, { "Et puis il y a Azj'Tordin, qui a fui le Prince, et qu'un diablotin a délesté de son livre de sorts en chemin. Il mourra, désormais, comme n'importe lequel d'entre vous. Et pour quoi ? Un peu d'air frais et beaucoup d'arbres." }, { "Vous êtes encore là. Comme c'est curieux. La plupart des visiteurs ont le bon sens de partir, à ce stade." } },
    revered = { title = "L'index", { "L'index sert à quelque chose. Il y a bien longtemps que personne ne m'a demandé à quoi il sert." }, { "Tout ce que cette maison a su, depuis bien avant que le monde se brise, est consigné quelque part dans ces salles, et je sais où. Chaque guerre, chaque sort, chaque prince insensé, chaque nom. Je tiens l'index pour que, si les Shen'dralar disparaissent un jour, et je soupçonne ce jour plus proche que le Prince ne le croit, ce que nous savions ne disparaisse pas avec nous. Le Prince aime dire qu'il garde la maison en vie. Moi, je garde ce qu'elle a su. Des deux, c'est mon ouvrage qui durera le plus." }, { "L'Athenaeum est immense, et ce n'est rien encore. Il attend des lecteurs qui ne viennent jamais. Rapportez-moi un de nos tomes, et je vous en arracherai peut-être une page. Oui, moi, qui tiens que rien d'écrit n'est sans valeur. Une page dans un livre que personne n'ouvre ne vaut guère mieux qu'un meuble. J'aime mieux perdre une page au profit d'un lecteur qu'un livre au profit de la poussière. Un mortel qui emporte une page d'ici reviendra peut-être un jour chercher le reste." } },
    aside = { title = "Déjà de retour", { "Déjà de retour ? Je vous avais réservé une heure, entre deux traités fort ennuyeux. N'en tirez aucune conclusion." } },
    exalted = { title = "Votre nom", { "Je connais votre nom." }, { "Ne vous rengorgez pas. C'est le premier nom de mortel que je prends la peine de garder depuis une éternité, et je l'ai classé. Chez moi, c'est ce qui ressemble le plus à de l'affection. Je l'ai classé en fort bonne place. Si vous saviez en quelle compagnie. Des généraux, des poètes, et une reine fort pénible." }, { "L'entrée est brève. Votre nom, et dessous une note de ma main. Elle tenait d'abord en un mot : « tenace ». J'ai ajouté plus tard « utile », puis, après une longue dispute avec moi-même, « $gbienvenu:bienvenue; ». J'ai barré ce dernier mot une fois. Il est revenu, et je l'ai laissé." }, { "Vous m'avez rapporté la vieille lame émoussée, et je vous ai dit ce qu'il faudrait pour lui rendre son fil, dragon compris. Je ne pensais revoir ni elle ni vous. Je me suis trompé, sur vous du moins, et je me trompe rarement, et cela aussi, je l'ai noté.", after = 7508 }, { "J'ai lu presque tout ce que cette maison a jamais consigné. Bien peu de choses m'y ont surpris, et aucune ces derniers temps. Vous, si, un peu, et plus d'une fois. Allez faire quelque chose qui mérite d'être ajouté. Je serai ici avec l'index, à être insupportable, et j'ai laissé de la place après votre nom." } },
  },
  [589] = {
    start = { title = "La viande", { "Bonjour. Peu de gens montent jusqu'ici, et ceux qui le font veulent en général un sabre." }, { "Vous en aurez peut-être un, au bout du compte, mais je n'ai pas seul mon mot à dire. Sur ce rocher, chaque sabre décide seul s'il vous portera, et aucun prix ne le fera changer d'avis. Il faudra nous gagner tous les deux, et les félins sont la moitié la plus difficile." }, { "Alors nous commençons là où commence tout jeune sabre, par la nourriture. Ils mangent beaucoup pendant le dressage. Les chimères et les ours de ces collines ont de la viande à revendre. Rapportez-m'en. C'est un travail simple, mais il importe, et ce sera la première d'une longue série." } },
    friendly = { title = "Encore", { "Bonne viande. Les sabres ont tout mangé." }, { "Je vous demanderai la même chose de nombreuses fois, et je la veux bien faite à chaque fois. C'est ainsi qu'apprend un jeune sabre. La leçon revient jusqu'à ne plus être une leçon, jusqu'à devenir simplement ce qu'est le félin." }, { "Il y a d'autres tâches, à présent. Les furbolgs Tombe-hiver ne sont plus eux-mêmes. Ils ont peur de tout, et une bête qui a peur tue sans choisir. Je n'ai jamais levé la main sur eux, et j'espérais ne jamais avoir à le faire. Mais ils viennent trop près du rocher, et je ne veux pas d'eux près des jeunes. Repoussez-les. Les petits ne devraient pas apprendre la peur si tôt." } },
    honored = { title = "La reine", { "Il y a une vieille histoire sous tout cela, et vous l'avez méritée." }, { "Il y a longtemps, la reine des sabres était tombée entre les mains de géants en furie, et Tyrande Whisperwind l'en a tirée. Depuis ce jour, mon peuple et les sabres-de-givre sont amis. La reine s'appelle Shy-Rotam. Je pense à ce sauvetage chaque fois qu'un félin me laisse approcher. C'était un vieux bienfait, et les félins n'ont jamais cessé de le rendre." }, { "Les géants ne sont pas partis. Les Cognegivre sont les mêmes, et ils ne sont pas loin. Je vous demande de les combattre en son nom. Pour moi, c'est une dette, et vous aideriez à la payer. Je ne le demanderais pas à quelqu'un contre qui les sabres feulent encore." }, { "Je vous estime davantage chaque fois que vous montez jusqu'ici." } },
    revered = { title = "Le petit", { "Quand un petit arrive chez moi, il refuse de manger dans ma main. Il prend la nourriture sur la neige une fois que j'ai reculé, et il feule en mangeant. Chaque jour, je pose la viande un peu plus près de moi. Et un beau jour, il vient la prendre entre mes doigts. Je n'ai jamais su dire quel jour ce serait. J'ai seulement appris à continuer de poser la viande." }, { "Hier soir, je me suis rendu compte que je fais la même chose avec vous. La viande, la même tâche encore et encore, les furbolgs, les géants. Un peu plus près chaque fois. Je ne l'avais pas prévu. Je ne connais pas d'autre façon d'enseigner." }, { "Les sabres connaissent votre odeur, maintenant. Quand vous montez le sentier, les jeunes lèvent la tête, puis la reposent. Chez un sabre, c'est une grande politesse." }, { "J'aurais dû vous demander si cela vous gênait. Vous n'êtes pas $gparti:partie;. Chez un petit, c'est la réponse, et je l'ai prise pour la vôtre." } },
    aside = { title = "À mi-chemin", { "À mi-chemin. Les jeunes ne lèvent même plus la tête quand vous montez le sentier. Ils connaissent votre pas. La première fois, il m'a fallu toute une année pour en arriver là." } },
    exalted = { title = "La monture", { "J'ai une monture pour vous." }, { "Une femelle que j'ai élevée depuis qu'elle était toute petite. De tous, c'est elle qui a mis le plus longtemps à manger dans ma main, et elle a été la plus têtue pour tout le reste. Je me suis dit que vous vous entendriez bien. Elle m'a mordu plus d'une fois avant de me faire confiance. Vous, elle ne vous a jamais $gmordu:mordue;. Je le prends pour un signe." }, { "Elle vous portera où vous voudrez, par tous les temps. Elle se renferme si on la tient trop longtemps loin du froid. Laissez-lui un peu de neige de temps en temps." }, { "Le premier jour, je vous ai dit qu'il faudrait nous gagner tous les deux, et que les félins étaient la moitié la plus difficile. J'avais tout à l'envers. Les jeunes ont fait la paix avec vous bien avant moi. J'ai vécu si longtemps parmi les félins qu'une personne me prend plus de temps qu'un petit. Vous êtes $grevenu:revenue; quand même, jour après jour, comme je reviens poser la viande pour eux. Le petit, c'était moi." }, { "Allez doucement, la première fois. Elle n'a encore jamais quitté le rocher." } },
  },
  [21] = {
    start = { title = "Des clients tranquilles", { "Baie-du-Butin, partenaire. Ici, tout le monde est partenaire jusqu'à preuve du contraire." }, { "Prenez un verre. Dépensez un peu d'argent. Je ne demande qu'une chose à mes clients, c'est qu'il ne se passe rien pendant leur séjour. Rien du tout. Mes videurs s'y entendent très bien, et ils touchent un petit supplément quand il le faut." }, { "Vous n'êtes encore personne pour moi, et je le dis gentiment. La plupart des gens de cette baie ne sont personne pour moi. Ceux qui comptent sont ceux qui font quelque chose pour le cartel Gentepression, et pour le gobelin qui tient son port. Faites quelque chose, et nous en reparlerons." } },
    friendly = { title = "À quoi sert la baie", { "Alors. On m'a dit que vous rendiez des services au cartel. Vous pouvez maintenant savoir à quoi sert cette baie." }, { "Baie-du-Butin a sa propre flotte, et cette flotte est à moi. Les Écumeurs des Flots noirs partent de ce port, et mon amiral garde les routes ouvertes à quiconque paie le cartel. Au-delà de la pointe, une flotte aux voiles rouges aimerait bien ces routes pour elle seule, et pour moi, c'est une affaire personnelle. Pour quiconque boit mon alcool aussi." }, { "À l'intérieur des terres, KapitalRisk dépouille la jungle de son bois et de son minerai. Ce sont des gobelins eux aussi, et cela n'a jamais suffi à dire dans quel camp se range un gobelin. Je n'ai jamais aimé les gobelins qui creusent assez près pour que je les entende." }, { "Continuez, et la baie commencera à vous faire de la place." } },
    honored = { title = "La collection", { "Entrez. Ne touchez à rien." }, { "Je collectionne. Surtout des objets trolls, de l'empire qui tenait cette jungle bien avant que quiconque songe à y bâtir un port. Des masques, des idoles, des lames que personne ne peut soulever. Les Gurubashi faisaient de belles choses pour de terribles raisons, et les raisons ne m'ont jamais gêné." }, { "Il y avait une pièce que je désirais plus que toutes les autres. La Pierre des marées. J'en ai lu la légende dans un vieux recueil de contes trolls : une pierre qui renferme une marée, et une malédiction sur celui qui la porte, qui s'efface du monde et y revient. On disait qu'un sorcier gobelin du nom de Gazban l'avait trouvée. Gazban s'est révélé être un fantôme. Voilà pour la malédiction qui ne serait qu'une légende." }, { "Elle trône à présent sur son propre socle, et la marée qu'elle renferme ne cesse jamais de bouger. C'est vous qui me l'avez apportée, et Gazban repose enfin. Personne d'autre n'y a touché depuis, et personne n'y touchera.", after = 611 } },
    revered = { title = "Des oreilles", { "Krazek écoute pour moi. Il ne quitte guère la taverne, il entend chaque rumeur qui débarque, les plus étranges surtout, et il me les monte par l'escalier. D'autres en font autant, dont vous ne saurez jamais le nom. Krazek a l'oreille fine et la mémoire courte pour les visages. Pour son travail, c'est dans le bon ordre. Presque tout ce qui se dit dans ma baie me parvient avant que ceux qui le disent aient fini leur verre." }, { "C'est ainsi qu'un baron reste baron. Ceux qui me contrarient n'ont plus l'occasion d'en parler ensuite, parce que je l'apprends le premier. La solitude, c'est ce qu'imaginent les visiteurs. En réalité, il s'agit surtout de savoir ce qui monte l'escalier." }, { "Votre nom a souvent monté cet escalier, depuis cette baie et depuis les autres villes du cartel, qui m'en disent plus qu'elles ne l'avouent. J'ai tout écouté. J'ai fait surveiller des gens pour moins que cela, et j'en ai récompensé pour moins encore, et je n'ai jamais hésité sur ce que chacun méritait. Avec vous, un temps, j'ai hésité." } },
    exalted = { title = "L'escalier", { "Krazek a monté l'escalier ce matin avec votre nom, et je l'ai renvoyé en bas. Il l'a mal pris. Écouter, c'est la seule chose pour laquelle on l'ait jamais félicité." }, { "Je lui ai dit que je n'en aurais plus besoin, pour vous. De tous ceux qui vont et viennent dans cette baie, vous êtes la seule personne pour qui je ne tends plus l'oreille. Il m'a fallu longtemps pour y arriver, et je ne suis toujours pas sûr d'aimer l'effet que cela fait." }, { "Le premier jour, je ne vous ai demandé qu'une chose, qu'il ne se passe rien pendant votre séjour. Je la reprends. Vous avez été $gle client le plus mouvementé:la cliente la plus mouvementée; que cette baie ait connu depuis des années, et chaque événement a tourné à mon avantage. Faites tout le remue-ménage qui vous plaira." }, { "Les voiles rouges croisent toujours au-delà de la pointe, KapitalRisk creuse toujours assez près pour que je l'entende, et il y aura toujours quelqu'un dans l'escalier pour se dire que le dernier étage lui irait mieux qu'à moi. C'est la baie, et je ne la changerais pas. Elle est un peu plus facile à tenir avec une personne en qui j'ai confiance sans vérifier." } },
  },
  [369] = {
    start = { title = "Le prix de l'eau", { "Hé, vous ! Vous avez soif ? Évidemment. On est à Tanaris." }, { "Ingénieur en chef, Compagnie des eaux de Gadgetzan. Je fais tourner les puits, j'alimente les pompes et je maintiens un prix honnête. Honnête pour la Compagnie, j'entends. À Gadgetzan, absolument tout se paie, l'eau plus que le reste, et si c'est de la compassion que vous cherchez au lieu de l'eau, il y en a tout un désert derrière la porte." }, { "Les nomades, là-bas, vous diront que l'eau devrait être gratuite. Ce sont aussi eux qui nous ont pris nos puits, et qui ont tué ceux qui les entretenaient." } },
    friendly = { title = "Justice", { "Ah, voilà enfin quelqu'un à qui la Compagnie peut parler !" }, { "La situation est la suivante. Les nomades Bat-le-désert ont fait main basse sur presque tous les puits du désert. Nos puits. Nous les avons creusés, nous les avons alimentés, nous avons envoyé nos gens les entretenir, et les nomades ont tué ces gens et gardé l'eau. Certains parleraient d'un litige commercial. La Compagnie appelle ça du vol, avec des morts." }, { "Leur chef s'appelle Caliph Dard-de-scorpide. La Compagnie a fait dessiner sa tête sur une affiche et écrire un prix dessous, et c'est un joli prix." }, { "Tout ce que vous avez fait pour la Compagnie, la Compagnie l'a remarqué, et elle n'oublie pas qui l'a aidée. Un jour, ces puits nous reviendront. J'ai l'intention d'être devant le premier, une clé à molette à la main." } },
    honored = { title = "Le bâtonnet", { "Vous voulez savoir comment un gobelin trouve de l'eau dans une mer de sable ? L'ingénierie ! Et un bâton, aussi." }, { "Le bâtonnet divino-matic. On arpente les dunes avec, et quand il y a de l'eau tout au fond, il le sait, et on creuse, et la Compagnie a un nouveau puits. Chaque nouveau trou que j'ai creusé a commencé avec ce bâtonnet entre mes mains. Je préférerais perdre une main." }, { "Et puis le sergent Bly a demandé à me l'emprunter. Emprunter ! Il l'a emporté chasser le trésor chez les trolls de Zul'Farrak, avec une bande d'aventuriers de la pire espèce, et il ne l'a jamais rendu. Celui qui vole l'or d'un gobelin est un voleur. Celui qui vole le bâtonnet d'un gobelin en pleine sécheresse, c'est quelque chose que je n'ai pas le droit de dire devant la clientèle." }, { "Il trouve de nouveau de l'eau depuis qu'il est rentré. La Compagnie a cessé de me demander d'où viennent les nouveaux trous, et moi, j'ai cessé d'expliquer.", after = 2768 } },
    revered = { title = "La neige", { "La Compagnie a un grand projet, et je suis le seul à l'avoir dessiné." }, { "Dun Morogh ! Là-haut, les nains ont des sources si froides que l'eau vous fait mal aux dents. Plus d'eau qu'ils ne savent qu'en faire. La glace leur tombe du ciel, gratuitement, tout l'hiver ! Un jour, on la fera venir par des tuyaux, ou par bateau, ou on la taillera en blocs pour la traîner de l'autre côté de la mer, et Gadgetzan n'aura plus jamais soif. Plus personne ne se battra pour un seau. Plus personne ne mourra près d'un puits. Et je pourrai arrêter de vendre des sources d'énergie à des gens qui les font tomber dans le sable." }, { "En attendant, je vends de l'eau, de l'énergie et de la patience, et je fais payer les trois. L'argent sert à quelque chose, c'est tout ce que je dis. J'ai un tiroir plein de plans pour ça, et un plan d'arbre à sources d'énergie. La Compagnie m'a prié de ne plus apporter celui-là en réunion." }, { "J'aimerais vivre assez longtemps pour que l'eau m'ennuie. Imaginez un peu. Un gobelin de Tanaris que l'eau ennuie." } },
    exalted = { title = "C'est la maison qui offre", { "Tendez les mains." }, { "C'est une tasse d'eau. Fraîche et claire, du puits profond, le bon. Elle est gratuite. Je me suis entraîné à le dire. Ça sonne toujours aussi bizarre." }, { "Ne faites pas cette tête. Je sais ce que j'ai dit le premier jour, je le pensais, et je le pense toujours pour tous les autres. À Gadgetzan, tout se paie. Mais la Compagnie vous doit quelque chose, et la Compagnie paie ce qu'elle doit, et aujourd'hui la Compagnie, c'est moi, et je dis que celle-ci, c'est la maison qui l'offre." }, { "Tout ce que vous avez fait pour cette ville, vous l'avez fait pour un endroit qui vous faisait payer chaque gorgée, et vous avez continué. Vous m'avez supporté. Mes propres ingénieurs vous diraient que c'est le plus dur." }, { "Et puis il y a le calife. La Compagnie a payé la prime pour lui, et je n'y ai rien ajouté, parce que l'argent de la Compagnie est à la Compagnie. Cette tasse, elle, est à moi.", after = 2781 }, { "Buvez lentement. Elle a meilleur goût quand personne ne vous la fait payer. Si l'on apprend que l'Ingénieur en chef a donné de l'eau, il y aura une file d'attente jusqu'au bout de la rue avant midi, et je nierai tout." } },
  },
  [470] = {
    start = { title = "Les quais", { "Gazlowe. C'est moi qui tiens Cabestan. Les navires arrivent, les navires repartent, les marchandises changent de mains, je prélève ma petite part, et tout le monde rentre content. Ça, c'est la théorie." }, { "La pratique, c'est les pirates. Les Flibustiers des Mers du Sud attaquent mes navires tout le long de cette côte, et depuis peu ils ont planté leurs tentes à deux pas de mes quais. Les princes marchands ont englouti une fortune dans les flottes censées les arrêter, et il me manque toujours une lentille, une caisse de bottes et une bonne nuit de sommeil." } },
    friendly = { title = "Les gages", { "Hé ! Vous commencez à apparaître dans mes registres, et du bon côté." }, { "Cabestan fonctionne comme ça. Tous ceux qui comptent sont à mes gages. Le maître des quais, les videurs, le type qui surveille les videurs. Dizzywig tient les registres du port, et je me fie à ses registres parce que je le paie." }, { "Et puis il y a ceux qu'on ne peut pas payer. Les pirates, surtout. Et le vice-amiral dont le seul travail est de dégager ces eaux, et qui ne dégagerait pas une baignoire. Chaque fois qu'un Flibustier passe devant la flotte de Grezzlik avec ma cargaison à bord, je le note. J'ai tout un carnet de Grezzlik." }, { "Ce que vous faites pour le cartel, vous ne le faites pas pour mon argent. Je paie trop mal pour ça. Je cherche encore pour quoi vous le faites." } },
    honored = { title = "L'Insouciant", { "L'Insouciant m'a croisé une fois en mer, il y a des années. Quelle coque. Longue, basse et rapide, construite, je le jurerais, par quelqu'un qui aimait les bateaux plus que l'argent. Je connais la maladie. J'ai encore un croquis de ses lignes quelque part." }, { "Son capitaine, c'était le baron de Longrivage, de Gilnéas, et il se servait de ce bateau magnifique pour harceler les miens au profit des Flibustiers. J'ai mis son nom sur un avis de recherche, et je pensais chaque mot. J'espérais aussi, un peu, que celui qui l'abattrait laisserait le bateau en un seul morceau. On peut vouloir la mort d'un homme et tenir à son bateau." }, { "C'est comme ça, avec les pirates. Ils vous volent avec le meilleur travail des charpentiers de marine, vous les haïssez pour ça, et vous prenez des notes." }, { "Il ne harcèlera plus personne. J'ai payé la prime de bon cœur. Je n'ai jamais demandé ce qu'était devenu l'Insouciant. Il y a des choses dont un gobelin ne veut pas recevoir la facture.", after = 895 } },
    revered = { title = "Pas un sou à gagner", { "Mon observatoire, là-haut sur la colline. Ne me demandez pas ce qu'il rapporte." }, { "Une caravane m'a apporté la première lentille depuis Durotar. Un navire devait m'apporter la seconde, et les pirates ont eu le navire. J'ai failli tout laisser tomber." }, { "Et puis vous êtes $gentré:entrée; dans leur camp, vous en êtes $gressorti:ressortie; avec, et maintenant, par nuit claire, le ciel descend jusqu'à Cabestan.", after = 888 }, { "On me demande ce qu'un gobelin peut bien vouloir aux étoiles. Il n'y a pas un sou à gagner. C'est tout leur charme." }, { "Pareil pour l'équipe de course de Pozzik. Je lui trouve des pièces dans chaque port que j'ai, et une fois, je me suis noirci les mains sur un de leurs engins, et je n'ai jamais été aussi heureux sur un quai depuis. Aucun profit là-dedans. Aucun. Les gnomes réduisent toujours l'écart, et moi, je continue d'envoyer des pièces." }, { "Tout le reste de ce que je possède rapporte de l'argent. Ces deux-là me donnent juste envie de me lever le matin. Undermine voudrait sa part de ça aussi." } },
    exalted = { title = "Ce que j'ai bâti", { "J'ai bâti beaucoup de choses dans ma vie." }, { "Une ville, une fois, pour un chef de guerre orc qui payait à l'heure. Vous seriez surpris de savoir comme c'est rare. Ce port, planche par planche. Un observatoire que personne n'avait demandé. Des conduites de carburant pour des bolides qui ne gagneront peut-être jamais. Je pourrais vous dire ce qui est entré dans chacun, jusqu'au dernier clou." }, { "Le problème, c'est que j'ai l'argent pour une chose de plus, et deux plans sur la table. Une digue au-delà des quais, pour empêcher les Flibustiers de venir jusqu'à mes entrepôts. Ou un vrai phare sur la pointe, pour que plus aucun honnête marin ne s'échoue en arrivant de nuit. La digue est raisonnable. Le phare est beau. J'hésite depuis un mois, et je perds à chaque fois." }, { "Alors je vous le demande. Vous avez fait plus pour ce cartel que la plupart des gobelins qui y sont nés, et vous n'avez pas un sou en jeu d'un côté ou de l'autre. Choisissez. Je le bâtirai, et quand on me demandera pourquoi celui-là, je dirai de qui venait l'idée." }, { "Prenez votre temps. Pas trop. Le bois ne baisse pas." } },
  },
  [577] = {
    start = { title = "Premier jour", { "Oh ! Bonjour ! Vous êtes $gnouveau:nouvelle;. À Long-Guet, tout le monde est nouveau pendant à peu près une journée, et ensuite on a juste froid, comme nous tous." }, { "Moi, c'est Umi. J'habite ici. Une gnome dans un comptoir gobelin, là-haut où se croisent toutes les routes du Berceau-de-l'Hiver, avec rien d'autre derrière les murs que de la neige et des bêtes qui veulent vous manger. Ça me plaît. Ici, on construit, on troque, on se dispute." }, { "Mes amis sont malins. Chacun d'eux a toujours une idée géniale en cours, et ils ne me laissent jamais l'oublier. Un jour, j'en aurai une meilleure. Je n'ai pas encore décidé laquelle." } },
    friendly = { title = "Les nouvelles vont vite", { "Vous saviez que les gobelins d'ici parlent des gens des autres villes ? Tout le temps !" }, { "C'est comme ça que marche le cartel. Il y a quatre villes gobelines, la baie, Gadgetzan, Cabestan et nous. Elles sont très loin les unes des autres et elles cancanent comme des voisines. Aidez l'une, et les autres le savent à la caravane suivante, et voilà que les gobelins d'ici sont plus aimables avec vous qu'ils ne l'ont jamais été avec moi, et pourtant j'habite ici depuis une éternité." }, { "Ça ne me dérange pas. Enfin, un peu. Mais c'est agréable d'être l'amie de quelqu'un que toute la ville apprécie. Legacki m'a posé des questions sur vous pas plus tard qu'hier. J'ai répondu que vous étiez très $ggentil:gentille;, très $gcourageux:courageuse; et terriblement $gdoué:douée; pour garder les secrets." }, { "Ce qui me fait penser. Vous savez garder un secret ?" } },
    honored = { title = "Le projet", { "Promettez de ne le dire à personne. Promettez !" }, { "Je vais construire un yéti. Un yéti mécanique, avec de la vraie fourrure de Chardon de glace et les plus grandes cornes, les belles, pas abîmées, et des engrenages dedans, et il va marcher droit sur mes amis et leur faire une peur bleue. Legacki ici, Sprinkle dans le désert, et Quixxil dans le cratère. Tous les trois. Et puis, quand ils auront fini de hurler, ils le regarderont vraiment, ils verront comme il est bien fait, et ils seront impressionnés." }, { "C'est ça, l'important. Les hurlements, c'est pour rire. Leur admiration, voilà ce que je veux." }, { "C'est idiot ? C'est un peu idiot. L'ingénierie l'est souvent, au début." }, { "Et vous l'avez fait ! Vous avez porté mon yéti jusqu'à chacun d'eux. Legacki a lâché un plateau entier. Sprinkle ne veut toujours pas me parler. Je crois que ça veut dire que ça a marché.", after = 5163 } },
    revered = { title = "Pourquoi ça comptait", { "Quand mes amis ont une idée, tout le monde écoute. Quand j'en ai une, on rit d'abord et on écoute ensuite, quand on écoute. Ils ne sont pas méchants. C'est presque pire. Ils trouvent juste ça drôle que la gnome ait des idées, elle aussi." }, { "Le yéti, c'était ma réponse. J'ai passé un long hiver à fabriquer quelque chose dont ils ne pourraient pas rire, chaque ressort, chaque boulon de sa mâchoire. Je voulais tellement qu'ils arrêtent de rire que j'en ai oublié de m'amuser, un moment." }, { "Je me demande pour qui je construis. Pour ceux qui rient, ou pour ceux qui demandent. Legacki dit que je réfléchis trop pour un yéti. Legacki n'a jamais rien construit qui marche. Je n'ai pas encore trouvé la réponse. Mais je m'en approche." }, { "Vous m'avez aidée, et vous n'avez pas ri une seule fois. Vous avez demandé comment ça marchait. Vous avez pris soin des cornes. J'y ai pensé bien plus qu'à leurs hurlements.", after = 5163 } },
    exalted = { title = "Vous d'abord", { "J'ai une nouvelle idée. Une bonne. Elle est dessinée sur l'établi, et c'est la chose la plus astucieuse que j'aie jamais imaginée, et personne au monde n'est au courant, à part moi. Et maintenant vous." }, { "La surprise, c'est que je vous la montre avant de la montrer à mes amis. Avant, je courais toujours les voir en premier, tout essoufflée, en attendant de savoir s'ils allaient rire. Je ne veux plus faire ça. Je veux la montrer à quelqu'un qui demandera comment ça marche." }, { "On me demande pourquoi une gnome vit en haut du monde. La vérité, c'est que le froid garde tout le monde à l'intérieur, à bavarder, et que j'adore ces bavardages, même quand ils parlent de moi. Ces temps-ci, ils parlent de vous, et j'ai arrêté de m'en vexer, que les gobelins vous aiment autant. Certains jours, je me dis qu'ils ont meilleur goût que je ne le croyais." }, { "Et vous pouvez construire votre propre yéti, maintenant ! Allez faire peur à quelqu'un de ma part. Quelqu'un qui le mérite.", after = 8798 }, { "Alors. Dites-moi ce que vous en pensez. Et si c'est une idée idiote, dites-le aussi. Je vous fais confiance pour ça." } },
  },
  [87] = {
    start = { title = "L'odeur de la baie", { "Vous sentez la baie. La monnaie Gentepression et le savon gobelin." }, { "Toute âme qui fait les courses de Revilgaz est une ennemie de la Voile sanglante, et nous autres, on a la mémoire longue pour les ennemis et aucune patience pour eux. J'en ai connu des tas qui trimaient pour les gobelins, jusqu'au jour où ils ont comparé c'que paie la baie et c'que paie la mer." }, { "La mer est vaste. La baie, c'est la seule chose dessus qui dise à un gars de la Voile où il a pas le droit d'aller. Un jour, vous en aurez peut-être assez des gobelins. Y a un navire rouge qui embauche, et à bord, personne vous demandera d'où vous venez." } },
    friendly = { title = "Les deux gorges", { "Tiens donc. Les videurs de la baie empoignent leur gourdin quand vous entrez. Bien. C'est le premier accueil honnête qu'un gobelin ait jamais fait à quiconque." }, { "Vous avez saigné la baie un bon moment pour en arriver là, et vous savez c'que ça a coûté. Toutes les villes gobelines ont votre nom sur une liste, maintenant, et c'est pas la liste où vous voudriez être." }, { "Les couleurs vous vont bien. Celui qui les portait avant les a jamais vraiment remplies, et la tempête l'a pris.", after = 9272 }, { "La baie a deux gorges qui comptent. L'amiral Seahorn, qui garde leurs navires sur l'eau, et le baron, qui garde leur loi à terre. Tranchez les deux, et les gobelins apprendront qu'il y a sur cette mer un pavillon qu'ils peuvent pas acheter." } },
    honored = { title = "L'équipage", { "Honoré, hein. Bien peu sur ce navire sont allés aussi loin avec nous, et la plupart sont nés dans le métier." }, { "Je vous ai pris comme on prend un couteau. Un couteau, c'est utile, et vous en prenez soin, et vous revenez. Aujourd'hui, je vous confierais la barre, et j'y laisse même pas approcher ma propre mère." }, { "Vous avez fait c'que j'ai demandé, les deux, et vous êtes $gressorti:ressortie; de la baie pour le raconter. Le chapeau vous va bien, $gamiral:amirale;. Y en a pas un autre comme lui sur la mer. Chaque fois que vous traversez le pont avec, l'équipage se redresse, et ils se rendent même pas compte qu'ils le font.", after = 4621 }, { "Y en a qui repartent, vous savez. De temps en temps, un des miens a le mal des draps propres et de la bière gobeline, et la baie le reprend, contre paiement, et après, on l'appelle traître. Je leur en veux pas tant que ça. La mer est dure avec les gens." }, { "Avant qu'ils partent, je leur donne toujours le même conseil. Le pardon d'un gobelin coûte de l'argent. Celui de la mer coûte rien, et elle m'a jamais demandé de m'essuyer les bottes." } },
  },
  [349] = {
    start = { title = "Le chemin", { "Bienvenue, bienvenue, bienvenue ! Personne ne trouve cette maison par hasard. Ou bien nous voulions qu'on vous trouve, ou bien mes gardes se sont relâchés, et je saurai lequel des deux avant le souper." }, { "Ravenholdt est une maison de mains fines. Des voleurs, des assassins, des gens capables d'ôter une bague d'un doigt sans que le doigt s'en aperçoive. Nous avons nos querelles, naturellement. Les restes de l'Alterac se sont baptisés le Syndicat, tiennent leurs couteaux par le mauvais bout, et ne cessent de se multiplier." }, { "Vous n'êtes pas des miens, et je ne saurais dire encore ce que vous êtes. Montrez-le-moi, et sans bruit. Le silence, c'est ce qui me manque toujours." } },
    friendly = { title = "Les emblèmes", { "Ah ! Vous avez fait les poches du Syndicat. Je le sens toujours." }, { "Chacun d'eux porte un emblème, et chaque emblème que vous dérobez est une petite honte pour celui qui le portait. Nous avons rarement besoin de la lame. Un gars du Syndicat sans emblème a déjà perdu ce qui comptait pour lui, et ce qui l'attend chez les siens ne me regarde pas. Je tiens cela pour le plus joli travail que cette maison ait jamais accompli." }, { "Voilà tout notre art, voyez-vous. La finesse d'abord. La force quand la finesse échoue, et elle échoue bien moins souvent que ne le croient ceux qui préfèrent la force. N'importe qui peut ouvrir une gorge. Très peu savent ouvrir une bourse dans une rue bondée et la refermer." }, { "Vous avez servi cette maison, et les gardes vous font signe de passer, à la grille. C'est à cela que ressemble un accueil, à Ravenholdt." } },
    honored = { title = "Les serrures", { "Vous êtes donc du métier. Je m'en doutais, à votre façon de vous tenir." }, { "Vous apportez des coffrets à Fahrad, à ce qu'on me dit. De lourdes petites boîtes têtues et laides, et il les confie aux jeunes parce qu'une serrure est le maître le plus honnête du monde. Elle se moque de qui vous êtes, de qui était votre père, de votre envie qu'elle s'ouvre. Elle s'ouvre quand vos mains sont justes, et pas un instant avant. Vous laissez quelques pièces dans chacune, paraît-il, pour que les jeunes aient une raison d'insister. De l'encouragement, dit Fahrad. J'appelle cela un appât, et j'approuve. On raconte que j'étais un piètre élève, autrefois. Ce n'est pas le souvenir que j'en ai." }, { "La patience et les mains. Tout le reste de ce que nous enseignons n'est qu'ornement sur ces deux-là. La plupart de ceux qui viennent ici ont l'une des deux. Très peu ont les deux, et ce sont ceux-là que je retiens. Je pense à vous depuis un moment." } },
    revered = { title = "Le sac", { "J'ai perdu quelque chose, un jour." }, { "Un petit sac bleu. Ce qu'il renferme est mon affaire, et le restera. Des voleurs l'ont pris, ce qui en dit long sur leur talent, puis n'ont pas su l'ouvrir, ce qui en dit long sur ses limites. Alors ils ont trouvé acheteur pour un mystère verrouillé, un chaman d'Azshara qui y a vu une relique. Un objet sacré n'est jamais que ce dont l'acheteur a besoin. Puis les voleurs sont morts, comme meurent ceux qui me volent, et il me restait un sac hors d'atteinte et une clé partie en pire endroit encore, dans l'antre d'un drake vert, au fond d'un temple englouti." }, { "C'était la seule serrure que je n'arrivais pas à laisser tranquille. Je me réveillais la nuit, les doigts déjà en mouvement. J'ai voulu très peu de choses ainsi dans ma vie, et jamais une si petite." }, { "La clé est revenue avec vous. Je l'ai ouvert la nuit même, seul, porte verrouillée, et ce qu'il renfermait m'a illuminé les mains. Je suis resté longtemps avec cette lumière avant de laisser entrer qui que ce soit.", after = 8236 } },
    exalted = { title = "L'élève", { "Je n'ai plus rien à vous apprendre." }, { "C'est la phrase la plus difficile de mon métier, et je n'ai jamais pris plaisir à la prononcer. Un maître n'est un maître que tant qu'un élève a besoin de lui. Vous n'avez pas besoin de moi. Vos mains valent les miennes, certains jours mieux, et votre patience a survécu à toutes les épreuves que cette maison pouvait dresser. C'est la meilleure chose arrivée à Ravenholdt depuis des années, et je le pense, même s'il m'en a coûté de m'y faire." }, { "Alors je vais vous donner du travail, à la place. Il y a dans la cour une gamine, tout en coudes et en culot, qui ne saurait pas ouvrir un coffret pour sauver sa peau. Apprenez-lui. Elle me rappelle quelqu'un, sans que je sache dire qui. Avec vos mains, pas avec mes mots. Les miens ne lui font plus rien, et je soupçonne que les vôtres n'auront pas besoin d'être nombreux." }, { "Et portez ce que je vous ai donné. Le mot a fait le tour de la maison et des camps du Syndicat, et personne n'a cherché à le mettre à l'épreuve. C'est presque dommage.", after = 8236 }, { "Je serai dans la grand-salle, à guetter le déclic depuis la cour." } },
  },
  [92] = {
    start = { title = "La terre des Gelkis", { "Vous foulez la terre des Gelkis, et elle ne vous connaît pas." }, { "J'entends la terre. Elle me dit qui marche sur elle, de quel poids, et ce qu'il porte dans son cœur. Vous, elle ne sait pas encore vous lire, alors aucune place ne vous attend à nos feux." }, { "Les Magram sont nos ennemis. Ils sont bruyants, et ils croient que leur force suffit. La terre est plus forte que la force. Quand la terre connaîtra votre nom, je vous parlerai. D'ici là, repartez par où vous êtes $gvenu:venue;." } },
    friendly = { title = "Ce que dit la terre", { "La terre est lourde de Magram, à présent, et c'est vous qui l'avez alourdie. C'est bien. Maintenant, nous allons parler." }, { "Écoutez. Les Gelkis ne se battent pas seulement avec des lances. Nous nous battons avec ce que nous donne le sol. Nous croyons que la mère des centaures, Theradras, repose sous cette terre, et que la terre est sa voix. Nous gardons ses larmes dans notre caverne, et tant que nous les gardons, elle nous garde." }, { "Les Magram disent que personne ne protège les centaures. Ils le disent fort, et ils n'écoutent rien. Alors ils perdront. Un clan qui n'écoute rien n'a rien qui l'avertisse quand le sol bouge." }, { "Vous n'êtes pas Gelkis. Vous ne le serez jamais. Mais la terre ne tremble plus quand vous montez jusqu'au village, et chez les miens, c'est le premier mot de l'amitié." } },
    honored = { title = "La raison de votre venue", { "La terre m'a dit un secret sur vous." }, { "Votre peuple est venu en Désolace pour apprendre comment on vainc les centaures. Tous les centaures. Vous avez choisi les Gelkis parce que nous haïssons les Magram, et que la haine est une porte. Quand les Magram seront faibles, votre peuple se tournera vers les Gelkis, et il saura déjà comment nous briser. Je le savais depuis le début. Je vous ai laissé venir quand même." }, { "La terre ne ment pas, mais elle ne choisit pas. C'est moi qui choisis." }, { "Un cristal rouge est entré dans notre terre il y a peu, venu d'une terre brisée, loin au-delà de ce ciel, une terre de démons. Il est nouveau, étrange et fort, et la terre ne sait pas encore ce qu'il fera. Vous êtes comme ce cristal." }, { "Khan Jehn s'appuyait sur sa force comme sur un mur, et la terre est patiente avec les murs. Vos mains l'ont abattu, pour nous.", after = 1374 }, { "Quand votre peuple viendra briser les autres clans, qu'il laisse les Gelkis debout. C'est tout ce que je lui demande. À vous, je ne demande rien de plus. Vous êtes $gun ami:une amie;. Je le dis en sachant ce que je sais." } },
  },
  [93] = {
    start = { title = "Fort", { "Allez-vous-en. Les Magram tuent les faibles, et je ne sais pas encore ce que vous êtes." }, { "Les Gelkis prient une mère sous la terre. Ils croient qu'elle les garde. Personne ne garde les centaures ! Personne n'a jamais gardé les centaures. Nous nous gardons nous-mêmes, avec nos sabots et nos lances, et les Magram se gardent mieux que tous, parce que nous sommes les plus forts." }, { "Vous voulez parler à Warug ? Tuez des Gelkis. Puis revenez, et je saurai ce que vous êtes." } },
    friendly = { title = "Le rire", { "Ha ! Vous avez tué beaucoup de Gelkis. Leurs éclaireurs crachent votre nom, maintenant, comme ils crachent le nôtre. Bien !" }, { "Vous n'êtes pas un centaure, mais vous vous battez un peu comme un centaure. Vous riez quand vous vous battez ? Vous devriez. Un guerrier qui rit montre à l'ennemi que l'ennemi est petit, et l'ennemi le croit, et alors il est petit. C'est comme ça que les Magram se battent. Les Gelkis chantent aux pierres. Nous, on rit, et on gagne." }, { "Les Gelkis gardent des cristaux dans une caverne et les appellent les larmes de la mère. Des larmes ! Quand on les casse, la mère ne vient pas. Elle ne vient jamais. Un jour, je les casserai toutes, et les Gelkis sauront enfin ce que les Magram savent déjà." }, { "Maintenant, on parle, vous et Warug. Apportez-moi de quoi rire." } },
    honored = { title = "Le petit homme de bois", { "Un jour, un gnome pas plus grand qu'un enfant est sorti de la poussière derrière ses chevaux, avec une charrette de jouets. Des feux de couleur. De petites machines qui allaient sans souffle. C'était la chose la plus drôle que j'aie jamais rencontrée. Je l'ai tué. Il m'a fait rire d'abord, et je ne l'ai pas oublié." }, { "J'ai gardé le jouet que je préférais. Un homme de bois avec une main qui montait et descendait. Coucou, coucou, coucou. Un jour, je l'ai frappé, et il s'est défait dans mon poing. Je l'ai regretté. Warug ne regrette jamais. J'ai regretté le petit homme de bois." }, { "Vous m'en avez apporté un nouveau. Je l'ai fait bouger. Il se tient dans ma tente, et je ne le frappe pas. Je suis assez fort pour ne pas le frapper.", after = 1371 }, { "Shaka est mort, de votre main. Sa tête est sur une pique devant ma porte, pour que Shaka apprenne ce que sont les Magram.", after = 1375 }, { "Vous êtes $gfort:forte;, alors je vous le dis. Les Magram régneront sur la Désolace, et tous les autres clans seront sous nos sabots. Je vous aime bien. J'aime les choses bruyantes, et les combats, et le petit homme de bois. Maintenant, je vous aime bien aussi." } },
  },
  [2778] = {
    start = { title = "Le ciel vide", { "Levez les yeux. Plus haut. Vous voyez les fées flotter autour de l'île et vous croyez que les vents nous tiennent encore compagnie. Elles n'en ont que l'apparence. Les esprits qui ont porté mon peuple jusqu'au Mur-Céleste, qui nous parlaient et tenaient cette île dans les airs, se taisent depuis longtemps." }, { "Les Sculpte-vents ont juré de découvrir où ils sont allés et de les ramener, quoi qu'il en coûte, jusqu'au bout de la route, et elle descend. Prenez-la avec nous, ou prenez-la là où ma parole ne vous suit pas." } },
    friendly = { title = "Ce que nous devons", { "Vous êtes $gresté:restée;. Alors on vous doit la vérité sur ce que veut dire se tenir aux côtés des Sculpte-vents." }, { "Les esprits nous ont fait leurs dons, instruments et assemblages, et nous veillons encore sur eux. Nous lisons le vent, parce que le vent est le dernier d'entre eux qui bouge encore. Et nous surveillons la terre. Elle s'ouvre, les lignes telluriques montent à travers elle, et ces plaies, nous les appelons des cicatrices. Les magistères de l'Ordre suprême préfèrent étudier une cicatrice plutôt que de demander ce qui l'a faite." }, { "Les Al'Aketh, nous ne les surveillons pas. Nous leur répondons, à chaque fois. Cela, je ne l'adoucis pour personne." }, { "Ce que vous faites pour nous n'est pas une faveur. Cela fait partie d'une dette, et cette dette est la nôtre." }, { "Le sanctuaire est tombé et sa prêtresse a fui. Ce qui protégeait cette île du seigneur des Vents n'est plus. Je lis le ciel chaque nuit, maintenant. Pour l'instant, il n'a fait que me rendre mon regard.", after = 93836 } },
  },
  [2779] = {
    start = { title = "Ce que nous avons oublié", { "Vous nous trouvez en pleine recherche. Un ordre d'érudits qui a perdu presque tout ce qu'il savait ne fait guère autre chose." }, { "Nous sommes seuls, désormais. Les vents qui ont porté mon peuple jusqu'au Mur-Céleste sont partis, et je le dis franchement parce que la plupart des gens de l'île n'y arrivent toujours pas. Nous étions autrefois des érudits bien-nés, et quelque part dans les longues années qui ont suivi, nous avons oublié comment faire tout ce que les vents ne faisaient pas à notre place. L'Ordre suprême entend s'en souvenir." }, { "Il y a du travail ici pour quiconque veut bien chercher." } },
    friendly = { title = "Sous nos pieds", { "Certains viennent à l'Ordre suprême parce qu'ils y sont nés, d'autres parce qu'ils l'ont choisi, et j'ai cessé de demander lesquels. Ce qui compte, c'est ce que vous en ferez." }, { "Nous cherchons ce que nos ancêtres savaient avant que les vents ne rendent le savoir inutile : les arcanes d'Eldre'Thalas, une force qui ne dépend de la bonté de personne. Un archimage du Kirin Tor, à Dalaran, répond à mes lettres, ce que les vents n'ont pas fait depuis longtemps. Azeroth a continué d'apprendre pendant que nous dérivions. Elle nous enseignera, si nous sommes assez humbles pour demander." }, { "Les Sculpte-vents nous trouvent imprudents. Vous les entendrez le dire. Écoutez-les quand même, puis revenez ici faire le travail." }, { "J'ai envoyé Belathaan au sanctuaire pour parler. J'avais la certitude qu'on pouvait parler. Depuis, j'ai peu de certitudes, et je trouve que je travaille mieux ainsi.", after = 92834 } },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Forgefer"] = "Ironforge", ["Rochenoire"] = "Blackrock", ["Cabestan"] = "Ratchet", ["Long-Guet"] = "Long-guet" }
